# ---- terrain-CLASS map (encounter routing) ---------------------------------
# STATIC address (not the relocating tile arena): u16 W, u16 H, then W*H class
# bytes. class -> (rate_zone, terrain_type) via 0x08945810; terrain 0 = the zoned
# LAND table every vanilla canoe river uses. Carved river cells inherit the class
# of what they replaced (mountain/ocean/marsh) -> ocean-pool fights or rate_zone 6
# (rate 1..3 = never). The client rewrites these cells to RIVER_CLASS so encounters
# behave exactly like a vanilla river. Rebuilt by the game on overworld load, so
# the client re-applies alongside the grid edits (canary-checked).
TERRAINMAP_ADDR = 0x089B2884
TERRAINMAP_DATA_OFF = 4                   # past the u16 W, u16 H header
TERRAINMAP_W = TERRAINMAP_H = 255
RIVER_CLASS = 7                        # rate_zone 3, terrain 0 (zoned land)

